export function Spacer({
  size = {{size}},
  axis = "{{axis}}",
  accent = "{{accent}}",
  guide = {{guide}},
}) {
  const vertical = axis === "vertical";
  return (
    <div style={{ display: "flex", flexDirection: vertical ? "column" : "row", alignItems: vertical ? "stretch" : "center", fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430", background: "#FAF7F2", padding: 16 }}>
      <div style={{ background: "#fff", border: "1px solid #24143022", borderRadius: 6, padding: 14, textAlign: "center", flex: vertical ? undefined : "none" }}>Block A</div>
      <div style={{ position: "relative", height: vertical ? size : "auto", width: vertical ? "auto" : size, flex: vertical ? undefined : "none", outline: guide ? `1px dashed ${accent}` : "none" }}>
        {guide && <span style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%, -50%)", background: "#FAF7F2", padding: "0 4px", fontWeight: 700, whiteSpace: "nowrap", color: accent }}>{size}px</span>}
      </div>
      <div style={{ background: "#fff", border: "1px solid #24143022", borderRadius: 6, padding: 14, textAlign: "center", flex: vertical ? undefined : "none" }}>Block B</div>
    </div>
  );
}
